import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
} from '@jinx-ui/react';

interface ContactsData {
  fullName: string;
  email: string;
}

interface AddressData {
  city: string;
  address: string;
}

interface RegistrationFormProps {
  onSubmit: (data: { contacts: ContactsData; address: AddressData }) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [contacts, setContacts] = useState<ContactsData>({ fullName: '', email: '' });
  const [address, setAddress] = useState<AddressData>({ city: '', address: '' });

  const emailError =
    contacts.email.length > 0 && !contacts.email.includes('@')
      ? 'Укажите адрес с символом @'
      : undefined;

  const canGoNext =
    step === 0
      ? contacts.fullName.trim().length > 0 && contacts.email.trim().length > 0 && !emailError
      : step === 1
        ? address.city.trim().length > 0 && address.address.trim().length > 0
        : true;

  const goBack = () => setStep((current) => Math.max(current - 1, 0));
  const goNext = () => setStep((current) => Math.min(current + 1, steps.length - 1));

  const handlePrimaryAction = () => {
    if (step === steps.length - 1) {
      onSubmit({ contacts, address });
      return;
    }
    goNext();
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r)',
        maxWidth: '480px',
      }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <JxInputField
            label="Полное имя"
            required
            value={contacts.fullName}
            onChange={(event) =>
              setContacts((current) => ({ ...current, fullName: event.target.value }))
            }
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={contacts.email}
            onChange={(event) =>
              setContacts((current) => ({ ...current, email: event.target.value }))
            }
            errorText={emailError}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <JxInputField
            label="Город"
            required
            value={address.city}
            onChange={(event) =>
              setAddress((current) => ({ ...current, city: event.target.value }))
            }
          />
          <JxTextareaField
            label="Адрес"
            required
            rows={3}
            value={address.address}
            onChange={(event) =>
              setAddress((current) => ({ ...current, address: event.target.value }))
            }
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <p style={{ color: 'var(--jx-text-2)' }}>Проверьте данные перед отправкой:</p>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            <span>
              <strong>Имя:</strong> {contacts.fullName}
            </span>
            <span>
              <strong>Почта:</strong> {contacts.email}
            </span>
            <span>
              <strong>Город:</strong> {address.city}
            </span>
            <span>
              <strong>Адрес:</strong> {address.address}
            </span>
          </div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-r-sm)' }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        <JxButton
          variant="primary"
          type="button"
          disabled={!canGoNext}
          onClick={handlePrimaryAction}
        >
          {step === steps.length - 1 ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </div>
  );
}

